{
  "terms": [
    {
      "id": "term_routine_functions",
      "label": "routine functions",
      "aliases": [],
      "source_refs": ["F025"]
    },
    {
      "id": "term_medical_treatment",
      "label": "medical treatment",
      "aliases": [],
      "source_refs": ["F036:F039"]
    },
    {
      "id": "term_first_aid",
      "label": "first aid",
      "aliases": [],
      "source_refs": ["F040:F054"]
    }
  ],
  "extractions": [
    {
      "unit": "F002",
      "unit_attributes": {
        "defines_term": null,
        "term_refs": null,
        "statement": "You must consider an injury or illness to meet the general recording criteria, and therefore to be recordable, if it results in any of the following: death, days away from work, restricted work or transfer to another job, medical treatment beyond first aid, or loss of consciousness.",
        "actor": "You",
        "actor_quote": "You",
        "kind": "requirement",
        "modality": "must"
      }
    },
    {
      "unit": "F002",
      "unit_attributes": {
        "defines_term": null,
        "term_refs": null,
        "statement": "You must consider a case to meet the general recording criteria if it involves a significant injury or illness diagnosed by a physician or other licensed health care professional, even if it does not result in death, days away from work, restricted work or job transfer, medical treatment beyond first aid, or loss of consciousness.",
        "actor": "You",
        "actor_quote": "You",
        "kind": "requirement",
        "modality": "must"
      }
    },
    {
      "unit": "F003:F009",
      "unit_attributes": {
        "defines_term": null,
        "term_refs": null,
        "statement": "A work-related injury or illness must be recorded if it results in one or more of the following: death; days away from work; restricted work or transfer to another job; medical treatment beyond first aid; loss of consciousness; or a significant injury or illness diagnosed by a physician or other licensed health care professional.",
        "actor": null,
        "actor_quote": null,
        "kind": "requirement",
        "modality": "must",
        "references": [
          "§ 1904.7(b)(2)",
          "§ 1904.7(b)(3)",
          "§ 1904.7(b)(4)",
          "§ 1904.7(b)(5)",
          "§ 1904.7(b)(6)",
          "§ 1904.7(b)(7)"
        ]
      }
    },
    {
      "unit": "F010",
      "unit_attributes": {
        "defines_term": null,
        "term_refs": null,
        "statement": "You must record an injury or illness that results in death by entering a check mark on the OSHA 300 Log in the space for cases resulting in death.",
        "actor": "You",
        "actor_quote": "You",
        "kind": "requirement",
        "modality": "must"
      }
    },
    {
      "unit": "F010",
      "unit_attributes": {
        "defines_term": null,
        "term_refs": null,
        "statement": "You must report any work-related fatality to OSHA within eight (8) hours, as required by § 1904.39.",
        "actor": "You",
        "actor_quote": "You",
        "kind": "requirement",
        "modality": "must",
        "references": ["§ 1904.39"]
      }
    },
    {
      "unit": "F011",
      "unit_attributes": {
        "defines_term": null,
        "term_refs": null,
        "statement": "When an injury or illness involves one or more days away from work, you must record the injury or illness on the OSHA 300 Log with a check mark in the space for cases involving days away and an entry of the number of calendar days away from work in the number of days column.",
        "actor": "you",
        "actor_quote": "you",
        "kind": "requirement",
        "modality": "must"
      }
    },
    {
      "unit": "F011",
      "unit_attributes": {
        "defines_term": null,
        "term_refs": null,
        "statement": "If the employee is out for an extended period of time, you must enter an estimate of the days that the employee will be away, and update the day count when the actual number of days is known.",
        "actor": "you",
        "actor_quote": "you",
        "kind": "requirement",
        "modality": "must"
      }
    },
    {
      "unit": "F012",
      "unit_attributes": {
        "defines_term": null,
        "term_refs": null,
        "statement": "You do not count the day on which the injury occurred or the illness began; you begin counting days away on the day after the injury occurred or the illness began.",
        "actor": "you",
        "actor_quote": "you",
        "kind": "statement",
        "modality": "not_stated"
      }
    },
    {
      "unit": "F013",
      "unit_attributes": {
        "defines_term": null,
        "term_refs": null,
        "statement": "When a physician or other licensed health care professional recommends that the worker stay at home but the employee comes to work anyway, you must record these injuries and illnesses on the OSHA 300 Log using the check box for cases with days away from work and enter the number of calendar days away recommended by the physician or other licensed health care professional.",
        "actor": "You",
        "actor_quote": "You",
        "kind": "requirement",
        "modality": "must"
      }
    },
    {
      "unit": "F013",
      "unit_attributes": {
        "defines_term": null,
        "term_refs": null,
        "statement": "If a physician or other licensed health care professional recommends days away, you should encourage your employee to follow that recommendation.",
        "actor": "you",
        "actor_quote": "you",
        "kind": "recommendation",
        "modality": "should"
      }
    },
    {
      "unit": "F013",
      "unit_attributes": {
        "defines_term": null,
        "term_refs": null,
        "statement": "Days away must be recorded whether the injured or ill employee follows the physician or licensed health care professional's recommendation or not.",
        "actor": null,
        "actor_quote": null,
        "kind": "requirement",
        "modality": "must"
      }
    },
    {
      "unit": "F013",
      "unit_attributes": {
        "defines_term": null,
        "term_refs": null,
        "statement": "If you receive recommendations from two or more physicians or other licensed health care professionals, you may make a decision as to which recommendation is the most authoritative, and record the case based upon that recommendation.",
        "actor": "you",
        "actor_quote": "you",
        "kind": "permission",
        "modality": "may"
      }
    },
    {
      "unit": "F014",
      "unit_attributes": {
        "defines_term": null,
        "term_refs": null,
        "statement": "When a physician or other licensed health care professional recommends that the worker return to work but the employee stays at home anyway, you must end the count of days away from work on the date the physician or other licensed health care professional recommends that the employee return to work.",
        "actor": "you",
        "actor_quote": "you",
        "kind": "requirement",
        "modality": "must"
      }
    },
    {
      "unit": "F015",
      "unit_attributes": {
        "defines_term": null,
        "term_refs": null,
        "statement": "You must count the number of calendar days the employee was unable to work as a result of the injury or illness, regardless of whether or not the employee was scheduled to work on those day(s).",
        "actor": "You",
        "actor_quote": "You",
        "kind": "requirement",
        "modality": "must"
      }
    },
    {
      "unit": "F015",
      "unit_attributes": {
        "defines_term": null,
        "term_refs": null,
        "statement": "Weekend days, holidays, vacation days or other days off are included in the total number of days recorded if the employee would not have been able to work on those days because of a work-related injury or illness.",
        "actor": null,
        "actor_quote": null,
        "kind": "statement",
        "modality": "not_stated"
      }
    },
    {
      "unit": "F016",
      "unit_attributes": {
        "defines_term": null,
        "term_refs": null,
        "statement": "In a case where a worker is injured or becomes ill on a Friday, reports to work on a Monday, and was not scheduled to work on the weekend, you need to record the case only if you receive information from a physician or other licensed health care professional indicating that the employee should not have worked, or should have performed only restricted work, during the weekend; if so, you must record the injury or illness as a case with days away from work or restricted work, and enter the day counts, as appropriate.",
        "actor": "you",
        "actor_quote": "you",
        "kind": "requirement",
        "modality": "must"
      }
    },
    {
      "unit": "F017",
      "unit_attributes": {
        "defines_term": null,
        "term_refs": null,
        "statement": "In a case where a worker is injured or becomes ill on the day before scheduled time off such as a holiday, a planned vacation, or a temporary plant closing, you need to record the case only if you receive information from a physician or other licensed health care professional indicating that the employee should not have worked, or should have performed only restricted work, during the scheduled time off; if so, you must record the injury or illness as a case with days away from work or restricted work, and enter the day counts, as appropriate.",
        "actor": "you",
        "actor_quote": "you",
        "kind": "requirement",
        "modality": "must"
      }
    },
    {
      "unit": "F018",
      "unit_attributes": {
        "defines_term": null,
        "term_refs": null,
        "statement": "You may cap the total days away from work at 180 calendar days.",
        "actor": "you",
        "actor_quote": "you",
        "kind": "permission",
        "modality": "may"
      }
    },
    {
      "unit": "F018",
      "unit_attributes": {
        "defines_term": null,
        "term_refs": null,
        "statement": "You are not required to keep track of the number of calendar days away from work if the injury or illness resulted in more than 180 calendar days away from work and/or days of job transfer or restriction, and in such a case, entering 180 in the total days away column will be considered adequate.",
        "actor": "You",
        "actor_quote": "You",
        "kind": "exemption",
        "modality": "not_required"
      }
    },
    {
      "unit": "F019",
      "unit_attributes": {
        "defines_term": null,
        "term_refs": null,
        "statement": "If an employee who is away from work because of an injury or illness leaves your company for some reason unrelated to the injury or illness, such as retirement, a plant closing, or to take another job, you may stop counting days away from work or days of restriction/job transfer.",
        "actor": "you",
        "actor_quote": "you",
        "kind": "permission",
        "modality": "may"
      }
    },
    {
      "unit": "F019",
      "unit_attributes": {
        "defines_term": null,
        "term_refs": null,
        "statement": "If an employee leaves your company because of the injury or illness, you must estimate the total number of days away or days of restriction/job transfer and enter the day count on the 300 Log.",
        "actor": "you",
        "actor_quote": "you",
        "kind": "requirement",
        "modality": "must"
      }
    },
    {
      "unit": "F020",
      "unit_attributes": {
        "defines_term": null,
        "term_refs": null,
        "statement": "If a case occurs in one year but results in days away during the next calendar year, you only record the injury or illness once, and you must enter the number of calendar days away for the injury or illness on the OSHA 300 Log for the year in which the injury or illness occurred.",
        "actor": "you",
        "actor_quote": "you",
        "kind": "requirement",
        "modality": "must"
      }
    },
    {
      "unit": "F020",
      "unit_attributes": {
        "defines_term": null,
        "term_refs": null,
        "statement": "If the employee is still away from work because of the injury or illness when you prepare the annual summary, you must estimate the total number of calendar days you expect the employee to be away from work, use this number to calculate the total for the annual summary, and then update the initial log entry later when the day count is known or reaches the 180-day cap.",
        "actor": "you",
        "actor_quote": "you",
        "kind": "requirement",
        "modality": "must"
      }
    },
    {
      "unit": "F021",
      "unit_attributes": {
        "defines_term": null,
        "term_refs": null,
        "statement": "When an injury or illness involves restricted work or job transfer but does not involve death or days away from work, you must record the injury or illness on the OSHA 300 Log by placing a check mark in the space for job transfer or restriction and an entry of the number of restricted or transferred days in the restricted workdays column.",
        "actor": "you",
        "actor_quote": "you",
        "kind": "requirement",
        "modality": "must"
      }
    },
    {
      "unit": "F022:F024",
      "unit_attributes": {
        "defines_term": null,
        "term_refs": ["term_routine_functions"],
        "statement": "Restricted work occurs when, as the result of a work-related injury or illness, you keep the employee from performing one or more of the routine functions of his or her job, or from working the full workday that he or she would otherwise have been scheduled to work, or a physician or other licensed health care professional recommends that the employee not perform one or more of the routine functions of his or her job, or not work the full workday that he or she would otherwise have been scheduled to work.",
        "actor": null,
        "actor_quote": null,
        "kind": "statement",
        "modality": "not_stated"
      }
    },
    {
      "unit": "F025",
      "unit_attributes": {
        "defines_term": "term_routine_functions",
        "term_refs": null,
        "statement": "For recordkeeping purposes, an employee's routine functions are those work activities the employee regularly performs at least once per week.",
        "actor": null,
        "actor_quote": null,
        "kind": "definition",
        "modality": "not_stated"
      }
    },
    {
      "unit": "F026",
      "unit_attributes": {
        "defines_term": null,
        "term_refs": null,
        "statement": "You do not have to record restricted work or job transfers if you, or the physician or other licensed health care professional, impose the restriction or transfer only for the day on which the injury occurred or the illness began.",
        "actor": "you",
        "actor_quote": "you",
        "kind": "exemption",
        "modality": "not_required"
      }
    },
    {
      "unit": "F027",
      "unit_attributes": {
        "defines_term": null,
        "term_refs": ["term_routine_functions"],
        "statement": "A recommended work restriction is recordable only if it affects one or more of the employee's routine job functions, and to determine whether this is the case, you must evaluate the restriction in light of the routine functions of the injured or ill employee's job.",
        "actor": "you",
        "actor_quote": "you",
        "kind": "requirement",
        "modality": "must"
      }
    },
    {
      "unit": "F027",
      "unit_attributes": {
        "defines_term": null,
        "term_refs": ["term_routine_functions"],
        "statement": "If the restriction from you or the physician or other licensed health care professional keeps the employee from performing one or more of his or her routine job functions, or from working the full workday the injured or ill employee would otherwise have worked, the employee's work has been restricted and you must record the case.",
        "actor": "you",
        "actor_quote": "you",
        "kind": "requirement",
        "modality": "must"
      }
    },
    {
      "unit": "F028",
      "unit_attributes": {
        "defines_term": null,
        "term_refs": null,
        "statement": "A partial day of work is recorded as a day of job transfer or restriction for recordkeeping purposes, except for the day on which the injury occurred or the illness began.",
        "actor": null,
        "actor_quote": null,
        "kind": "statement",
        "modality": "not_stated"
      }
    },
    {
      "unit": "F029",
      "unit_attributes": {
        "defines_term": null,
        "term_refs": ["term_routine_functions"],
        "statement": "If an injured or ill worker produces fewer goods or services than he or she would have produced prior to the injury or illness but otherwise performs all of the routine functions of his or her work, the case is not considered a restricted work case; the case is considered restricted work only if the worker does not perform all of the routine functions of his or her job or does not work the full shift that he or she would otherwise have worked.",
        "actor": null,
        "actor_quote": null,
        "kind": "statement",
        "modality": "not_stated"
      }
    },
    {
      "unit": "F030",
      "unit_attributes": {
        "defines_term": null,
        "term_refs": ["term_routine_functions"],
        "statement": "If you are not clear about the physician or other licensed health care professional's vague recommendation (such as light duty or taking it easy for a week), you may ask that person whether the employee can do all of his or her routine job functions and work all of his or her normally assigned work shift.",
        "actor": "you",
        "actor_quote": "you",
        "kind": "permission",
        "modality": "may"
      }
    },
    {
      "unit": "F030",
      "unit_attributes": {
        "defines_term": null,
        "term_refs": null,
        "statement": "If you inquire about a vague restriction and the physician or other licensed health care professional answers 'Yes' to whether the employee can do all routine job functions and work all normally assigned work shift, the case does not involve a work restriction and does not have to be recorded as such.",
        "actor": null,
        "actor_quote": null,
        "kind": "exemption",
        "modality": "not_required"
      }
    },
    {
      "unit": "F030",
      "unit_attributes": {
        "defines_term": null,
        "term_refs": null,
        "statement": "If you inquire about a vague restriction and the answer to one or both questions (regarding doing all routine job functions and working the full shift) is 'No', the case involves restricted work and must be recorded as a restricted work case.",
        "actor": null,
        "actor_quote": null,
        "kind": "requirement",
        "modality": "must"
      }
    },
    {
      "unit": "F030",
      "unit_attributes": {
        "defines_term": null,
        "term_refs": null,
        "statement": "If you are unable to obtain additional clarification from the physician or other licensed health care professional who recommended the vague restriction, you must record the injury or illness as a case involving restricted work.",
        "actor": null,
        "actor_quote": null,
        "kind": "requirement",
        "modality": "must"
      }
    },
    {
      "unit": "F031",
      "unit_attributes": {
        "defines_term": null,
        "term_refs": ["term_routine_functions"],
        "statement": "If a physician or other licensed health care professional recommends a job restriction meeting OSHA's definition, but the employee does all of his or her routine job functions anyway, you must record the injury or illness on the OSHA 300 Log as a restricted work case.",
        "actor": "You",
        "actor_quote": "You",
        "kind": "requirement",
        "modality": "must"
      }
    },
    {
      "unit": "F031",
      "unit_attributes": {
        "defines_term": null,
        "term_refs": null,
        "statement": "If a physician or other licensed health care professional recommends a job restriction, you should ensure that the employee complies with that restriction.",
        "actor": "you",
        "actor_quote": "you",
        "kind": "recommendation",
        "modality": "should"
      }
    },
    {
      "unit": "F031",
      "unit_attributes": {
        "defines_term": null,
        "term_refs": null,
        "statement": "If you receive recommendations from two or more physicians or other licensed health care professionals regarding a job restriction, you may make a decision as to which recommendation is the most authoritative, and record the case based upon that recommendation.",
        "actor": "you",
        "actor_quote": "you",
        "kind": "permission",
        "modality": "may"
      }
    },
    {
      "unit": "F032",
      "unit_attributes": {
        "defines_term": null,
        "term_refs": null,
        "statement": "If you assign an injured or ill employee to a job other than his or her regular job for part of the day, the case involves transfer to another job, not including the day on which the injury or illness occurred.",
        "actor": "you",
        "actor_quote": "you",
        "kind": "statement",
        "modality": "not_stated"
      }
    },
    {
      "unit": "F033",
      "unit_attributes": {
        "defines_term": null,
        "term_refs": null,
        "statement": "Both job transfer and restricted work cases are recorded in the same box on the OSHA 300 Log; you must record an injury or illness that involves a job transfer by placing a check in the box for job transfer.",
        "actor": "You",
        "actor_quote": "You",
        "kind": "requirement",
        "modality": "must"
      }
    },
    {
      "unit": "F034",
      "unit_attributes": {
        "defines_term": null,
        "term_refs": null,
        "statement": "You count days of job transfer or restriction in the same way you count days away from work, using § 1904.7(b)(3)(i) to (viii).",
        "actor": "You",
        "actor_quote": "You",
        "kind": "statement",
        "modality": "not_stated",
        "references": ["§ 1904.7(b)(3)(i) to (viii)"]
      }
    },
    {
      "unit": "F034",
      "unit_attributes": {
        "defines_term": null,
        "term_refs": ["term_routine_functions"],
        "statement": "If you permanently assign the injured or ill employee to a job that has been modified or permanently changed in a manner that eliminates the routine functions the employee was restricted from performing, you may stop the day count when the modification or change is made permanent.",
        "actor": "you",
        "actor_quote": "you",
        "kind": "permission",
        "modality": "may"
      }
    },
    {
      "unit": "F034",
      "unit_attributes": {
        "defines_term": null,
        "term_refs": null,
        "statement": "You must count at least one day of restricted work or job transfer for cases where an employee is permanently assigned to a modified or changed job that eliminates restricted routine functions.",
        "actor": "You",
        "actor_quote": "You",
        "kind": "requirement",
        "modality": "must"
      }
    },
    {
      "unit": "F035",
      "unit_attributes": {
        "defines_term": null,
        "term_refs": ["term_medical_treatment", "term_first_aid"],
        "statement": "If a work-related injury or illness results in medical treatment beyond first aid, you must record it on the OSHA 300 Log.",
        "actor": "you",
        "actor_quote": "you",
        "kind": "requirement",
        "modality": "must"
      }
    },
    {
      "unit": "F035",
      "unit_attributes": {
        "defines_term": null,
        "term_refs": ["term_medical_treatment"],
        "statement": "If the injury or illness results in medical treatment beyond first aid but did not involve death, one or more days away from work, one or more days of restricted work, or one or more days of job transfer, you enter a check mark in the box for cases where the employee received medical treatment but remained at work and was not transferred or restricted.",
        "actor": "you",
        "actor_quote": "you",
        "kind": "statement",
        "modality": "not_stated"
      }
    },
    {
      "unit": "F036:F039",
      "unit_attributes": {
        "defines_term": "term_medical_treatment",
        "term_refs": ["term_first_aid"],
        "statement": "Medical treatment means the management and care of a patient to combat disease or disorder, but for the purposes of part 1904 does not include visits to a physician or other licensed health care professional solely for observation or counseling; the conduct of diagnostic procedures, such as x-rays and blood tests, including the administration of prescription medications used solely for diagnostic purposes (e.g., eye drops to dilate pupils); or first aid as defined in paragraph (b)(5)(ii) of this section.",
        "actor": null,
        "actor_quote": null,
        "kind": "definition",
        "modality": "not_stated",
        "references": ["part 1904", "paragraph (b)(5)(ii)"]
      }
    },
    {
      "unit": "F040:F054",
      "unit_attributes": {
        "defines_term": "term_first_aid",
        "term_refs": ["term_medical_treatment"],
        "statement": "For the purposes of part 1904, first aid means the following list: (A) using a non-prescription medication at nonprescription strength (with the qualification that for medications available in both prescription and non-prescription form, a recommendation by a physician or other licensed health care professional to use a non-prescription medication at prescription strength is considered medical treatment for recordkeeping purposes); (B) administering tetanus immunizations (other immunizations, such as Hepatitis B vaccine or rabies vaccine, are considered medical treatment); (C) cleaning, flushing or soaking wounds on the surface of the skin; (D) using wound coverings such as bandages, Band-Aids, gauze pads, etc., or using butterfly bandages or Steri-Strips (other wound closing devices such as sutures, staples, etc., are considered medical treatment); (E) using hot or cold therapy; (F) using any non-rigid means of support, such as elastic bandages, wraps, non-rigid back belts, etc. (devices with rigid stays or other systems designed to immobilize parts of the body are considered medical treatment for recordkeeping purposes); (G) using temporary immobilization devices while transporting an accident victim (e.g., splints, slings, neck collars, back boards, etc.); (H) drilling of a fingernail or toenail to relieve pressure, or draining fluid from a blister; (I) using eye patches; (J) removing foreign bodies from the eye using only irrigation or a cotton swab; (K) removing splinters or foreign material from areas other than the eye by irrigation, tweezers, cotton swabs or other simple means; (L) using finger guards; (M) using massages (physical therapy or chiropractic treatment are considered medical treatment for recordkeeping purposes); or (N) drinking fluids for relief of heat stress.",
        "actor": null,
        "actor_quote": null,
        "kind": "definition",
        "modality": "not_stated",
        "references": ["part 1904"]
      }
    },
    {
      "unit": "F055",
      "unit_attributes": {
        "defines_term": null,
        "term_refs": ["term_first_aid"],
        "statement": "The list of treatments in § 1904.7(b)(5)(ii) is a complete list of all treatments considered first aid for part 1904 purposes; no other procedures are included in first aid.",
        "actor": null,
        "actor_quote": null,
        "kind": "statement",
        "modality": "not_stated",
        "references": ["part 1904", "§ 1904.7(b)(5)(ii)"]
      }
    },
    {
      "unit": "F056",
      "unit_attributes": {
        "defines_term": null,
        "term_refs": ["term_first_aid", "term_medical_treatment"],
        "statement": "OSHA considers the treatments listed in § 1904.7(b)(5)(ii) to be first aid regardless of the professional status of the person providing the treatment, even when provided by a physician or other licensed health care professional; similarly, OSHA considers treatment beyond first aid to be medical treatment even when provided by someone other than a physician or other licensed health care professional.",
        "actor": null,
        "actor_quote": null,
        "kind": "statement",
